def occurence(ch):
    f1 = open("adherent.dat", "rb")
    eof = False
    occ = 0
    while not eof:
        try:
            e = load(f1)
            if e["num"] == ch:
                occ += 1
        except:
            eof = True
    f1.close()
    return occ
