def calcul_bonus():
    f1 = open("adherent.dat", "rb")
    f2 = open("bonus.dat", "wb")
    eof = False
    while not eof:
        try:
            e2 = {}
            e = load(f1)
            b = (2023 - e["date"]["a"]) * 12 + (10 - e["date"]["m"])
            if b > 60:
                e2["num"] = e["num"]
                e2["bonus"] = b
                dump(e2, f2)
        except:
            eof = True
    f1.close()
    f2.close()
